content:
/* Reset & Base Variables */
:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-tertiary: #334155;
  --bg-card: rgba(30, 41, 59, 0.85);

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --accent-cyan: #06b6d4;
  --accent-cyan-glow: rgba(6, 182, 212, 0.4);
  --accent-green: #10b981;
  --accent-green-glow: rgba(16, 185, 129, 0.4);
  --accent-rose: #f43f5e;
  --accent-rose-glow: rgba(244, 63, 94, 0.3);
  --accent-amber: #f59e0b;
  --accent-purple: #8b5cf6;

  --font-base: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Hiragino Sans", "Meiryo", sans-serif;
  --font-mono: "JetBrains Mono", "SF Mono", Monaco, Consolas, "Courier New", monospace;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.2);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -2px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -4px rgba(0, 0, 0, 0.4);
  --shadow-neon: 0 0 20px rgba(6, 182, 212, 0.35);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-base);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  background-image: 
    radial-gradient(at 0% 0%, rgba(6, 182, 212, 0.12) 0px, transparent 50%),
    radial-gradient(at 100% 100%, rgba(139, 92, 246, 0.1) 0px, transparent 50%);
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Accessibility Focus Outline */
button:focus-visible,
input:focus-visible,
.btn:focus-visible,
.key-btn:focus-visible {
  outline: 2px solid var(--accent-cyan);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.4);
}

/* Main App Wrapper */
.typing-app {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 1.5rem 1rem 3rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  min-height: 100vh;
}

/* Header */
.app-header {
  text-align: center;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
}

.header-title {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #38bdf8 0%, #818cf8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* Stats Bar */
.stats-bar {
  display: flex;
  gap: 1rem;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.stat-badge {
  background: var(--bg-secondary);
  border: 1px solid var(--bg-tertiary);
  border-radius: var(--radius-md);
  padding: 0.6rem 1.2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 110px;
  box-shadow: var(--shadow-sm);
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.stat-badge:hover {
  border-color: rgba(6, 182, 212, 0.4);
}

.stat-badge-time {
  background: linear-gradient(145deg, #1e293b, #0f172a);
  border-color: rgba(6, 182, 212, 0.5);
  box-shadow: 0 0 12px rgba(6, 182, 212, 0.2);
}

.stat-badge-time .stat-value {
  color: var(--accent-cyan);
  font-weight: 800;
}

.stat-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-value {
  font-family: var(--font-mono);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.2;
}

/* Main Game Card */
.game-card {
  width: 100%;
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-lg);
  padding: 2.5rem 1.5rem;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  min-height: 220px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

/* Miss Typing Effect */
.shake-error {
  animation: shake 0.3s ease-in-out;
  border-color: var(--accent-rose) !important;
  box-shadow: 0 0 16px var(--accent-rose-glow), var(--shadow-lg) !important;
}

@keyframes shake {
  0%, 100% {
    transform: translateX(0);
  }
  20%, 60% {
    transform: translateX(-6px);
  }
  40%, 80% {
    transform: translateX(6px);
  }
}

/* Prompt Container */
.prompt-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  text-align: center;
}

.prompt-kanji {
  font-size: 2.2rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text-main);
}

.prompt-kana {
  font-size: 1.15rem;
  color: var(--text-muted);
  letter-spacing: 0.08em;
  min-height: 1.5rem;
}

.prompt-romaji {
  font-family: var(--font-mono);
  font-size: 1.6rem;
  letter-spacing: 0.12em;
  padding: 0.5rem 1rem;
  background: rgba(15, 23, 42, 0.6);
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 200px;
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.romaji-typed {
  color: var(--accent-green);
  font-weight: 600;
  text-shadow: 0 0 8px var(--accent-green-glow);
}

.romaji-current {
  color: var(--accent-cyan);
  font-weight: 800;
  border-bottom: 2px solid var(--accent-cyan);
  animation: pulse-cursor 1s infinite alternate;
  background-color: rgba(6, 182, 212, 0.15);
  border-radius: 2px;
  padding: 0 1px;
}

@keyframes pulse-cursor {
  0% {
    opacity: 0.6;
    box-shadow: 0 0 0 rgba(6, 182, 212, 0);
  }
  100% {
    opacity: 1;
    box-shadow: 0 0 8px var(--accent-cyan-glow);
  }
}

.romaji-untyped {
  color: var(--text-dim);
}

/* Typing Input Helper */
.typing-input-wrapper {
  position: absolute;
  opacity: 0;
  pointer-events: none;
  width: 0;
  height: 0;
}

.hidden-input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  pointer-events: none;
}

.mobile-input-helper {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  color: var(--text-dim);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

/* Controls */
.controls-container {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  width: 100%;
}

.btn {
  font-family: var(--font-base);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.75rem;
  min-height: 44px;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  outline: none;
  user-select: none;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background: linear-gradient(135deg, #06b6d4 0%, #3b82f6 100%);
  color: #ffffff;
  box-shadow: 0 4px 14px 0 rgba(6, 182, 212, 0.39);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #0891b2 0%, #2563eb 100%);
  box-shadow: 0 6px 20px 0 rgba(6, 182, 212, 0.5);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-main);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.btn-secondary:hover {
  background: #475569;
  border-color: rgba(255, 255, 255, 0.2);
}

/* Virtual Keyboard */
.keyboard-container {
  width: 100%;
  max-width: 720px;
  background: rgba(15, 23, 42, 0.6);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-lg);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  box-shadow: var(--shadow-md);
  user-select: none;
}

.keyboard-row {
  display: flex;
  justify-content: center;
  gap: 0.4rem;
  width: 100%;
}

.key-btn {
  flex: 1;
  max-width: 48px;
  min-height: 44px;
  height: 48px;
  background: var(--bg-secondary);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-sm);
  color: var(--text-main);
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.1s ease;
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.4);
}

.key-btn:hover {
  background: var(--bg-tertiary);
  border-color: rgba(255, 255, 255, 0.2);
}

.key-btn-active {
  background: var(--accent-cyan) !important;
  color: #042f2e !important;
  transform: translateY(2px) scale(0.96);
  box-shadow: 0 0 12px var(--accent-cyan-glow), inset 0 2px 4px rgba(0, 0, 0, 0.2) !important;
  border-color: var(--accent-cyan) !important;
  font-weight: 800;
}

.key-btn-space {
  flex: 5;
  max-width: 260px;
  min-height: 44px;
  font-size: 0.85rem;
  color: var(--text-dim);
}

/* Result Modal */
.result-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 1rem;
  animation: fadeIn 0.25s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.result-card {
  background: var(--bg-secondary);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-lg);
  padding: 2.25rem 2rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6), var(--shadow-neon);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  animation: scaleIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
}

@keyframes scaleIn {
  from {
    transform: scale(0.92);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

.result-title {
  font-size: 1.6rem;
  font-weight: 800;
  text-align: center;
  letter-spacing: -0.01em;
}

.result-hero {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.5rem;
  background: rgba(15, 23, 42, 0.5);
  padding: 1rem 2rem;
  border-radius: var(--radius-md);
  border: 1px solid rgba(6, 182, 212, 0.3);
  width: 100%;
}

.result-hero-number {
  font-family: var(--font-mono);
  font-size: 3.75rem;
  font-weight: 800;
  color: var(--accent-cyan);
  line-height: 1;
  text-shadow: 0 0 20px var(--accent-cyan-glow);
}

.result-hero-unit {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-muted);
}

/* Rank Badge */
.rank-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.35rem 1rem;
  border-radius: var(--radius-full);
  font-size: 1.1rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  background: var(--bg-tertiary);
  color: var(--text-main);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

/* Result Grid */
.result-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  width: 100%;
}

.result-item {
  background: rgba(15, 23, 42, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: var(--radius-md);
  padding: 0.85rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.result-item-label {
  font-size: 0.75rem;
  color: var(--text-dim);
  font-weight: 600;
}

.result-item-value {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
}

/* Result Actions */
.result-actions {
  width: 100%;
  display: flex;
  justify-content: center;
  margin-top: 0.5rem;
}

.result-actions .btn {
  width: 100%;
  font-size: 1.1rem;
  padding: 0.85rem 1.5rem;
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .typing-app {
    padding: 1rem 0.75rem 2rem 0.75rem;
    gap: 1.25rem;
  }

  .header-title {
    font-size: 1.6rem;
  }

  .game-card {
    padding: 1.75rem 1rem;
    min-height: 180px;
  }

  .prompt-kanji {
    font-size: 1.75rem;
  }

  .prompt-romaji {
    font-size: 1.3rem;
    padding: 0.4rem 0.75rem;
  }

  .stat-badge {
    min-width: 90px;
    padding: 0.5rem 0.75rem;
  }

  .stat-value {
    font-size: 1.25rem;
  }

  .btn {
    min-height: 44px;
    padding: 0.75rem 1.25rem;
  }

  .keyboard-container {
    padding: 0.6rem 0.4rem;
    gap: 0.35rem;
  }

  .keyboard-row {
    gap: 0.25rem;
  }

  .key-btn {
    min-height: 44px;
    height: 44px;
    font-size: 0.9rem;
    border-radius: 4px;
  }

  .key-btn-space {
    min-height: 44px;
    height: 44px;
  }

  .result-card {
    padding: 1.75rem 1.25rem;
  }

  .result-hero-number {
    font-size: 3rem;
  }
}

@media (max-width: 380px) {
  .key-btn {
    min-height: 44px;
    height: 44px;
    font-size: 0.8rem;
    padding: 0 2px;
  }

  .key-btn-space {
    min-height: 44px;
    height: 44px;
  }

  .stats-bar {
    gap: 0.5rem;
  }

  .stat-badge {
    min-width: 80px;
    padding: 0.4rem 0.5rem;
  }
}

export type WordDifficulty = 'easy' | 'normal' | 'hard';

export interface TypingWord {
  id: number;
  kanji: string;
  kana: string;
  romaji: string;
  difficulty?: WordDifficulty;
  category?: string;
  alternativeRomaji?: string[];
}

export type GameStatus = 'idle' | 'playing' | 'finished';

export interface TypingStats {
  correctChars: number;
  totalKeystrokes: number;
  missCount: number;
  completedWords: number;
  wpm: number;
  accuracy: number;
  elapsedSeconds?: number;
}

export interface VirtualKeyboardProps {
  activeKey: string | null;
  nextKey?: string | null;
  targetKey?: string | null;
  onKeyPress: (key: string) => void;
}

export interface ResultModalProps {
  stats: TypingStats;
  onRestart: () => void;
  onClose?: () => void;
}

import { VirtualKeyboardProps } from '../types';

interface ExtendedVirtualKeyboardProps extends VirtualKeyboardProps {
  nextKey?: string | null;
  targetKey?: string | null;
}

const KEYBOARD_ROWS = [
  ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', '-'],
  ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'],
  ['z', 'x', 'c', 'v', 'b', 'n', 'm'],
];

const VirtualKeyboard = ({
  activeKey,
  nextKey,
  targetKey,
  onKeyPress,
}: ExtendedVirtualKeyboardProps) => {
  const normalizedActiveKey = activeKey ? activeKey.toLowerCase() : null;
  const guideKey = (nextKey ?? targetKey)?.toLowerCase() ?? null;

  return (
    <div
      className="keyboard-container"
      aria-label="仮想キーボード"
      style={{ touchAction: 'manipulation' }}
    >
      {KEYBOARD_ROWS.map((row, rowIndex) => (
        <div key={rowIndex} className="keyboard-row">
          {row.map((char) => {
            const isActive = normalizedActiveKey === char;
            const isTarget = guideKey === char;
            const keyLabel = char === '-' ? 'ハイフン' : `${char.toUpperCase()}キー`;

            return (
              <button
                key={char}
                type="button"
                className={`key-btn ${isActive ? 'key-btn-active' : ''} ${
                  isTarget ? 'key-btn-target' : ''
                }`.trim()}
                aria-label={keyLabel}
                aria-pressed={isActive}
                style={{
                  touchAction: 'manipulation',
                  ...(isTarget && !isActive
                    ? {
                        borderColor: 'var(--accent-cyan)',
                        boxShadow: '0 0 8px var(--accent-cyan-glow)',
                      }
                    : {}),
                }}
                onClick={() => onKeyPress?.(char)}
              >
                {char.toUpperCase()}
              </button>
            );
          })}
        </div>
      ))}
      <div className="keyboard-row">
        <button
          type="button"
          className={`key-btn key-btn-space ${
            normalizedActiveKey === ' ' ? 'key-btn-active' : ''
          } ${guideKey === ' ' ? 'key-btn-target' : ''}`.trim()}
          aria-label="スペースキー"
          aria-pressed={normalizedActiveKey === ' '}
          style={{
            touchAction: 'manipulation',
            ...(guideKey === ' ' && normalizedActiveKey !== ' '
              ? {
                  borderColor: 'var(--accent-cyan)',
                  boxShadow: '0 0 8px var(--accent-cyan-glow)',
                }
              : {}),
          }}
          onClick={() => onKeyPress?.(' ')}
        >
          SPACE
        </button>
      </div>
    </div>
  );
};

export default VirtualKeyboard;

import { useEffect, useRef } from 'react';
import { ResultModalProps } from '../types';

const getRank = (chars: number): { rank: string; color: string } => {
  if (chars >= 260) return { rank: 'S+', color: '#38bdf8' };
  if (chars >= 200) return { rank: 'S', color: '#06b6d4' };
  if (chars >= 150) return { rank: 'A', color: '#10b981' };
  if (chars >= 100) return { rank: 'B', color: '#f59e0b' };
  if (chars >= 50) return { rank: 'C', color: '#8b5cf6' };
  return { rank: 'D', color: '#94a3b8' };
};

const ResultModal = ({ stats, onRestart }: ResultModalProps) => {
  const { rank, color } = getRank(stats?.correctChars ?? 0);
  const restartButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    restartButtonRef.current?.focus();

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') {
        e.preventDefault();
        onRestart?.();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [onRestart]);

  return (
    <div className="result-overlay" role="dialog" aria-modal="true" aria-labelledby="result-title">
      <div className="result-card">
        <h2 id="result-title" className="result-title">
          タイピング結果
        </h2>

        <div className="rank-badge" style={{ borderColor: color, color: color }}>
          ランク: {rank}
        </div>

        <div className="result-hero">
          <span className="result-hero-number">{stats?.correctChars ?? 0}</span>
          <span className="result-hero-unit">文字 / 60秒</span>
        </div>

        <div className="result-grid">
          <div className="result-item">
            <span className="result-item-label">入力速度 (WPM)</span>
            <span className="result-item-value">{stats?.wpm ?? 0}</span>
          </div>
          <div className="result-item">
            <span className="result-item-label">正確率</span>
            <span className="result-item-value">{stats?.accuracy ?? 0}%</span>
          </div>
          <div className="result-item">
            <span className="result-item-label">総打鍵数</span>
            <span className="result-item-value">{stats?.totalKeystrokes ?? 0}</span>
          </div>
          <div className="result-item">
            <span className="result-item-label">ミス打鍵</span>
            <span className="result-item-value">{stats?.missCount ?? 0}</span>
          </div>
          <div className="result-item">
            <span className="result-item-label">完走ワード数</span>
            <span className="result-item-value">{stats?.completedWords ?? 0} 問</span>
          </div>
        </div>

        <div className="result-actions">
          <button
            ref={restartButtonRef}
            type="button"
            className="btn btn-primary"
            autoFocus
            onClick={() => onRestart?.()}
          >
            もう一度挑戦する (Enter)
          </button>
        </div>
      </div>
    </div>
  );
};

export default ResultModal;

import { useState, useEffect, useRef, useCallback } from 'react';
import { GameStatus, TypingStats, TypingWord } from './types';
import { WORDS } from './words';
import VirtualKeyboard from './components/VirtualKeyboard';
import ResultModal from './components/ResultModal';
import './index.css';

const TOTAL_TIME = 60;

const getRandomWordIndex = (currentIndex: number, total: number): number => {
  if (total <= 1) return 0;
  let next = Math.floor(Math.random() * total);
  while (next === currentIndex) {
    next = Math.floor(Math.random() * total);
  }
  return next;
};

// Web Audio API による効果音再生
const playSound = (type: 'type' | 'miss' | 'complete') => {
  try {
    const AudioCtx =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;
    if (type === 'type') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(600, now);
      gain.gain.setValueAtTime(0.04, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
      osc.start(now);
      osc.stop(now + 0.05);
    } else if (type === 'miss') {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(160, now);
      gain.gain.setValueAtTime(0.08, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.16);
      osc.start(now);
      osc.stop(now + 0.16);
    } else if (type === 'complete') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.setValueAtTime(659.25, now + 0.08);
      gain.gain.setValueAtTime(0.06, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);
      osc.start(now);
      osc.stop(now + 0.22);
    }
  } catch {
    // オーディオ非対応または自動再生ブロック環境へのフォールバック
  }
};

const App = () => {
  const [gameStatus, setGameStatus] = useState<GameStatus>('idle');
  const [timeLeft, setTimeLeft] = useState<number>(TOTAL_TIME);
  const [currentWordIndex, setCurrentWordIndex] = useState<number>(0);
  const [currentRomaji, setCurrentRomaji] = useState<string>(WORDS[0].romaji);
  const [charIndex, setCharIndex] = useState<number>(0);
  const [correctChars, setCorrectChars] = useState<number>(0);
  const [missCount, setMissCount] = useState<number>(0);
  const [totalKeystrokes, setTotalKeystrokes] = useState<number>(0);
  const [completedWords, setCompletedWords] = useState<number>(0);
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const [isMissed, setIsMissed] = useState<boolean>(false);

  const inputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | null>(null);
  const keyTimeoutRef = useRef<number | null>(null);
  const missTimeoutRef = useRef<number | null>(null);

  const currentWord: TypingWord = WORDS[currentWordIndex] || WORDS[0];

  // タイマー停止ヘルパー
  const stopTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  // ゲーム終了
  const finishGame = useCallback(() => {
    stopTimer();
    setGameStatus('finished');
  }, [stopTimer]);

  // 次の単語を選択してリセット
  const selectNextWord = useCallback((currentIndex: number) => {
    const nextIndex = getRandomWordIndex(currentIndex, WORDS.length);
    const nextWord = WORDS[nextIndex];
    setCurrentWordIndex(nextIndex);
    setCurrentRomaji(nextWord.romaji);
    setCharIndex(0);
  }, []);

  // ゲームスタート
  const startGame = useCallback(() => {
    stopTimer();
    const initialIndex = Math.floor(Math.random() * WORDS.length);
    const initialWord = WORDS[initialIndex];
    setCurrentWordIndex(initialIndex);
    setCurrentRomaji(initialWord.romaji);
    setCharIndex(0);
    setCorrectChars(0);
    setMissCount(0);
    setTotalKeystrokes(0);
    setCompletedWords(0);
    setTimeLeft(TOTAL_TIME);
    setIsMissed(false);
    setGameStatus('playing');

    if (inputRef.current) {
      inputRef.current.focus();
    }
  }, [stopTimer]);

  // カウントダウンタイマー管理
  useEffect(() => {
    if (gameStatus === 'playing') {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            finishGame();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => {
      stopTimer();
    };
  }, [gameStatus, finishGame, stopTimer]);

  // クリーンアップ
  useEffect(() => {
    return () => {
      if (keyTimeoutRef.current !== null) clearTimeout(keyTimeoutRef.current);
      if (missTimeoutRef.current !== null) clearTimeout(missTimeoutRef.current);
    };
  }, []);

  // キーハイライトのアニメーション
  const triggerKeyHighlight = useCallback((key: string) => {
    setActiveKey(key);
    if (keyTimeoutRef.current !== null) {
      clearTimeout(keyTimeoutRef.current);
    }
    keyTimeoutRef.current = window.setTimeout(() => {
      setActiveKey(null);
    }, 120);
  }, []);

  // ミス発生時のアニメーションと効果音
  const triggerMissFeedback = useCallback(() => {
    setMissCount((prev) => prev + 1);
    setIsMissed(true);
    playSound('miss');

    if (missTimeoutRef.current !== null) {
      clearTimeout(missTimeoutRef.current);
    }
    missTimeoutRef.current = window.setTimeout(() => {
      setIsMissed(false);
    }, 280);
  }, []);

  // 打鍵入力ハンドラ（代替ローマ字対応）
  const handleKeyAction = useCallback(
    (inputChar: string) => {
      if (gameStatus !== 'playing') {
        if (gameStatus === 'idle') {
          startGame();
        }
        return;
      }

      triggerKeyHighlight(inputChar);
      setTotalKeystrokes((prev) => prev + 1);

      // 利用可能なローマ字候補（標準表記 + 代替表記）
      const candidates = [currentWord.romaji, ...(currentWord.alternativeRomaji || [])];
      const typedPrefix = currentRomaji.slice(0, charIndex);
      const expectedPrefix = (typedPrefix + inputChar).toLowerCase();

      // 現在の入力文字列と前方一致するローマ字表記を検索
      const matchedCandidate = candidates.find((cand) =>
        cand.toLowerCase().startsWith(expectedPrefix)
      );

      if (matchedCandidate) {
        // マッチした候補表記を採用して反映
        setCurrentRomaji(matchedCandidate);
        const nextCorrect = correctChars + 1;
        setCorrectChars(nextCorrect);

        const nextCharIndex = charIndex + 1;
        if (nextCharIndex >= matchedCandidate.length) {
          // 単語クリア
          setCompletedWords((prev) => prev + 1);
          playSound('complete');
          selectNextWord(currentWordIndex);
        } else {
          setCharIndex(nextCharIndex);
          playSound('type');
        }
      } else {
        // ミス打鍵
        triggerMissFeedback();
      }
    },
    [
      gameStatus,
      currentWord,
      currentRomaji,
      charIndex,
      correctChars,
      currentWordIndex,
      startGame,
      triggerKeyHighlight,
      triggerMissFeedback,
      selectNextWord,
    ]
  );

  // 物理キーボードイベント
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // 修飾キー単体押しは無視
      if (['Shift', 'Control', 'Alt', 'Meta', 'Tab', 'CapsLock'].includes(e.key)) {
        return;
      }

      // 未開始時または結果画面表示時にSpaceまたはEnterキーで開始・リトライ
      if ((gameStatus === 'idle' || gameStatus === 'finished') && (e.key === ' ' || e.key === 'Enter')) {
        e.preventDefault();
        startGame();
        return;
      }

      if (gameStatus === 'playing') {
        // 1文字のアルファベットまたはハイフン等の記号
        if (e.key.length === 1) {
          e.preventDefault();
          handleKeyAction(e.key);
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [gameStatus, handleKeyAction, startGame]);

  // 入力カードクリックでフォーカス維持
  const handleCardClick = () => {
    if (inputRef.current) {
      inputRef.current.focus();
    }
  };

  // 正確率の計算
  const accuracy =
    totalKeystrokes > 0
      ? Math.max(0, Math.min(100, Math.round((correctChars / totalKeystrokes) * 100)))
      : 100;

  // WPMの計算
  const elapsedMinutes = (TOTAL_TIME - timeLeft) / 60;
  const wpm =
    elapsedMinutes > 0 ? Math.round(correctChars / 5 / elapsedMinutes) : 0;

  const stats: TypingStats = {
    correctChars,
    totalKeystrokes,
    missCount,
    completedWords,
    wpm,
    accuracy,
  };

  // 現在のローマ字の分割表示
  const typedPart = currentRomaji.slice(0, charIndex);
  const currentChar = currentRomaji.slice(charIndex, charIndex + 1);
  const untypedPart = currentRomaji.slice(charIndex + 1);

  return (
    <div className="typing-app">
      <header className="app-header">
        <h1 className="header-title">60秒ローマ字タイピング</h1>
        <p className="header-subtitle">60秒間で何文字打てるか限界に挑戦しよう！</p>
      </header>

      <section className="stats-bar" aria-label="ゲーム状況">
        <div className="stat-badge stat-badge-time">
          <span className="stat-label">残り時間</span>
          <span className="stat-value">{timeLeft}秒</span>
        </div>
        <div className="stat-badge">
          <span className="stat-label">打てた文字数</span>
          <span className="stat-value">{correctChars}</span>
        </div>
        <div className="stat-badge">
          <span className="stat-label">正確率</span>
          <span className="stat-value">{accuracy}%</span>
        </div>
        <div className="stat-badge">
          <span className="stat-label">ミス数</span>
          <span className="stat-value">{missCount}</span>
        </div>
      </section>

      <main
        className={`game-card ${isMissed ? 'shake-error' : ''}`.trim()}
        onClick={handleCardClick}
      >
        <div className="prompt-container">
          <div className="prompt-kanji">{currentWord.kanji}</div>
          <div className="prompt-kana">{currentWord.kana}</div>
          <div className="prompt-romaji" aria-label="ローマ字ガイド">
            <span className="romaji-typed">{typedPart}</span>
            <span className="romaji-current">{currentChar}</span>
            <span className="romaji-untyped">{untypedPart}</span>
          </div>
        </div>

        <div className="typing-input-wrapper">
          <input
            ref={inputRef}
            type="text"
            className="hidden-input"
            aria-label="タイピング入力欄"
            autoComplete="off"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck="false"
            value=""
            onChange={(e) => {
              const val = e.target.value;
              if (val.length > 0) {
                handleKeyAction(val[val.length - 1]);
              }
            }}
          />
        </div>

        {gameStatus === 'idle' && (
          <div className="mobile-input-helper">
            スペースキーまたは下の「スタート」ボタンで計測を開始
          </div>
        )}
      </main>

      <section className="controls-container">
        {gameStatus === 'idle' && (
          <button type="button" className="btn btn-primary" onClick={startGame}>
            スタート（60秒計測）
          </button>
        )}
        {gameStatus === 'playing' && (
          <button type="button" className="btn btn-secondary" onClick={startGame}>
            リセット
          </button>
        )}
      </section>

      <VirtualKeyboard
        activeKey={activeKey}
        targetKey={currentChar}
        onKeyPress={handleKeyAction}
      />

      {gameStatus === 'finished' && (
        <ResultModal stats={stats} onRestart={startGame} />
      )}
    </div>
  );
};

export default App;
